/**
 * Generic page for reports computed on the server ({ title, columns, rows, totals, note }): report menu,
 * period and dimension filters, sortable table with search, totals row, and Excel / PDF / CSV export
 * through the shared exporter (RALGA header, period, generated by / at; exports are audited).
 */
import * as React from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { useQuery } from "react-query";
import { BarChart3, FileText } from "lucide-react";
import pocketbase from "@/lib/pocketbase";
import { exportReport, CellFormat } from "@/lib/exporter";
import ExportMenu from "@/components/enterprise/ExportMenu";
import { Card, CardHeader, Column, DataTable, DatePicker, DateRangeFilter, EmptyState, FilterBar, FilterSelect, Page, PageHeader, Select, StatusPill, fmtDate, fmtDateTime, sentence, statusWord } from "@/components/ims";
import { cn } from "@/utils";

export interface ServerReportResult {
  title: string;
  columns: { key: string; label: string; type: string }[];
  rows: Record<string, any>[];
  totals: Record<string, number>;
  note: string;
  generated_at: string;
}

type FilterKey = "from" | "to" | "supplier" | "department" | "account";

const FORMAT: Record<string, CellFormat> = { money: "money", number: "number", pct: "percent", date: "date" };
const NUMERIC = ["money", "number", "pct"];
const cellText = (type: string, v: any) => {
  if (v === null || v === undefined || v === "") return "—";
  if (type === "money") return Math.round(Number(v)).toLocaleString("en-US");
  if (type === "number") return Number(v).toLocaleString("en-US");
  if (type === "pct") return `${Number(v).toLocaleString("en-US")}%`;
  if (type === "date") return fmtDate(String(v));
  if (type === "status") return sentence(String(v));
  return String(v);
};
/** Money columns say the unit in the header; cells show numbers only. */
const headerOf = (c: { label: string; type: string }) => (c.type === "money" && !/RWF/i.test(c.label) ? `${c.label} (RWF)` : c.label);

export default function ServerReportPage({
  title, description, breadcrumbs, groups, run, filters, exportPermission, defaultFrom,
}: {
  title: string;
  description: string;
  breadcrumbs: { title: string; link: string }[];
  groups: { title: string; items: [string, string][] }[];
  run: (key: string, f: Record<string, string>) => Promise<ServerReportResult>;
  filters: FilterKey[];
  exportPermission?: string[];
  /** Start of the default period, e.g. the fiscal year start. */
  defaultFrom?: string;
}) {
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const first = groups[0]?.items[0]?.[0] || "";
  const key = params.get("r") || first;
  const [f, setF] = React.useState<Record<string, string>>({ from: defaultFrom || `${new Date().getFullYear()}-01-01`, to: new Date().toISOString().slice(0, 10), supplier: "", department: "", account: "" });
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState("");
  const ref = useQuery(["server-report-filters", filters.join()], async () => ({
    suppliers: filters.includes("supplier") ? await pocketbase.collection("suppliers").getFullList({ sort: "name", fields: "id,name" }) : [],
    departments: filters.includes("department") ? await pocketbase.collection("departments").getFullList({ sort: "name", fields: "id,name" }) : [],
    accounts: filters.includes("account") ? (await pocketbase.collection("bank_accounts").getFullList({ sort: "kind,code", fields: "id,code,name" })).map((a: any) => ({ id: a.id, name: `${a.code} · ${a.name}` })) : [],
  }));
  const active = Object.fromEntries(Object.entries(f).filter(([k]) => filters.includes(k as FilterKey)));
  const q = useQuery(["server-report", title, key, active], () => run(key, active), { keepPreviousData: true, enabled: Boolean(key) });
  const r = q.data;
  const label = groups.flatMap((g) => g.items).find(([k]) => k === key)?.[1] || r?.title || "Report";
  const rows = React.useMemo(() => {
    const s = search.trim().toLowerCase();
    let out = (r?.rows || []).filter((row) => !s || Object.values(row).some((v) => String(v ?? "").toLowerCase().includes(s)));
    if (sort) {
      const k = sort.replace(/^-/, "");
      const dir = sort.startsWith("-") ? -1 : 1;
      out = [...out].sort((a, b) => (a[k] > b[k] ? 1 : a[k] < b[k] ? -1 : 0) * dir);
    }
    return out;
  }, [r, search, sort]);
  const nameOf = (list: any[] | undefined, id: string) => list?.find((x) => x.id === id)?.name;
  const subtitle = [
    filters.includes("from") && f.from && `from ${fmtDate(f.from)}`,
    filters.includes("to") && f.to && `to ${fmtDate(f.to)}`,
    f.supplier && filters.includes("supplier") && nameOf(ref.data?.suppliers, f.supplier),
    f.department && filters.includes("department") && nameOf(ref.data?.departments, f.department),
    f.account && filters.includes("account") && nameOf(ref.data?.accounts, f.account),
  ].filter(Boolean).join(" · ");
  const pick = (k: string) => {
    setParams({ r: k });
    setSort("");
  };

  const doExport = (format: "xlsx" | "pdf" | "csv") =>
    exportReport({
      title: label, subtitle, rows, format, what: `report:${key}`, orientation: (r?.columns.length || 0) > 6 ? "landscape" : "portrait",
      totals: (r?.columns || []).filter((c) => r?.totals[c.key] !== undefined && ["money", "number"].includes(c.type)).map((c) => c.label),
      columns: (r?.columns || []).map((c) => ({ header: headerOf(c), value: (row: any) => row[c.key], format: FORMAT[c.type] || "text", width: c.type === "text" || c.type === "status" ? 24 : 14 })),
    });

  const hasTotals = Boolean(r && Object.keys(r.totals || {}).length);
  const columns: Column<any>[] = (r?.columns || []).map((c, ci) => ({
    key: c.key,
    header: headerOf(c),
    sortField: c.key,
    numeric: NUMERIC.includes(c.type),
    nowrap: c.type === "date" || /number|code|ref/i.test(c.key),
    clamp: c.type === "text" && ci > 0 && !/number|code|ref/i.test(c.key),
    className: cn(ci === 0 && "min-w-[200px] font-semibold"),
    total: hasTotals && ci > 0 && r!.totals[c.key] !== undefined ? cellText(c.type, r!.totals[c.key]) : undefined,
    cell: (row) => {
      const text = cellText(c.type, row[c.key]);
      if (ci === 0 && row.link) return <Link to={row.link} className="font-semibold text-ims-link hover:underline">{text}</Link>;
      if (c.type === "status") return statusWord(String(row[c.key] || "")) ? <StatusPill status={String(row[c.key])} /> : text;
      return text;
    },
  }));

  const chips = [
    ...(f.supplier && filters.includes("supplier") ? [{ key: "supplier", label: `Supplier: ${nameOf(ref.data?.suppliers, f.supplier) || "…"}`, onRemove: () => setF({ ...f, supplier: "" }) }] : []),
    ...(f.department && filters.includes("department") ? [{ key: "department", label: `Department: ${nameOf(ref.data?.departments, f.department) || "…"}`, onRemove: () => setF({ ...f, department: "" }) }] : []),
    ...(f.account && filters.includes("account") ? [{ key: "account", label: `Account: ${nameOf(ref.data?.accounts, f.account) || "…"}`, onRemove: () => setF({ ...f, account: "" }) }] : []),
  ];

  return (
    <Page>
      <PageHeader breadcrumbs={breadcrumbs.map((b, i) => ({ label: b.title, to: i < breadcrumbs.length - 1 && b.link !== "#" ? b.link : undefined }))} title={title} subtitle={description} />
      <div className="grid gap-4 lg:grid-cols-[232px_minmax(0,1fr)]">
        <div className="lg:hidden">
          <label htmlFor="server-report-pick" className="mb-1.5 block text-t-label text-ims-text">Report</label>
          <Select id="server-report-pick" value={key} onChange={(e) => pick(e.target.value)}>
            {groups.map((g) => <optgroup key={g.title} label={g.title}>{g.items.map(([k, l]) => <option key={k} value={k}>{l}</option>)}</optgroup>)}
          </Select>
        </div>
        <Card as="div" padded={false} className="hidden self-start p-3 lg:block">
          <nav aria-label="Reports" className="space-y-4">
            {groups.map((g) => (
              <div key={g.title}>
                <p className="mb-1 px-2 text-t-small font-semibold text-ims-muted">{g.title}</p>
                {g.items.map(([k, l]) => (
                  <button
                    key={k}
                    type="button"
                    onClick={() => pick(k)}
                    aria-current={k === key ? "page" : undefined}
                    className={cn("flex min-h-[36px] w-full items-center gap-2 rounded-control px-2 text-left text-t-body", k === key ? "bg-ims-info-bg font-semibold text-ims-primary" : "text-ims-body hover:bg-ims-hover")}
                  >
                    <FileText size={15} className="shrink-0 opacity-60" aria-hidden /> {l}
                  </button>
                ))}
              </div>
            ))}
          </nav>
        </Card>

        <Card padded={false} className="min-w-0">
          <div className="flex flex-wrap items-start justify-between gap-3 px-5 pt-5">
            <CardHeader className="mb-0" title={label} subtitle={`${subtitle || "All records"} · ${rows.length} ${rows.length === 1 ? "row" : "rows"}${r ? ` · made ${fmtDateTime(r.generated_at)}` : ""}`} />
            <ExportMenu onExport={doExport} permission={exportPermission} disabled={!rows.length} />
          </div>
          <FilterBar search={{ value: search, onChange: setSearch, placeholder: "Search in these results" }} chips={chips} onClear={() => setF({ ...f, supplier: "", department: "", account: "" })}>
            {filters.includes("from") ? (
              <DateRangeFilter label="Dates" from={f.from} to={f.to} onChange={(from, to) => setF({ ...f, from, to })} />
            ) : filters.includes("to") ? (
              <span className="inline-flex items-center gap-1.5">
                <span className="text-t-small font-semibold text-ims-muted">As of</span>
                <DatePicker value={f.to} onChange={(to) => setF({ ...f, to })} className="h-button w-[150px] text-t-body" />
              </span>
            ) : null}
            {filters.includes("supplier") && <FilterSelect label="Supplier" value={f.supplier} onChange={(v) => setF({ ...f, supplier: v })} options={(ref.data?.suppliers || []).map((s: any) => ({ value: s.id, label: s.name }))} />}
            {filters.includes("department") && <FilterSelect label="Department" value={f.department} onChange={(v) => setF({ ...f, department: v })} options={(ref.data?.departments || []).map((d: any) => ({ value: d.id, label: d.name }))} />}
            {filters.includes("account") && <FilterSelect label="Account" value={f.account} onChange={(v) => setF({ ...f, account: v })} options={(ref.data?.accounts || []).map((a: any) => ({ value: a.id, label: a.name }))} className="[&_select]:w-[240px]" />}
          </FilterBar>
          <div className="border-t border-ims-divider">
            <DataTable
              columns={columns}
              rows={rows}
              rowKey={(_, i) => String(i)}
              sort={sort}
              onSort={setSort}
              loading={q.isLoading}
              error={q.isError ? new Error((q.error as any)?.message || "You may not have access to this report.") : undefined}
              onRetry={() => q.refetch()}
              fetching={q.isFetching}
              onRowClick={rows.some((row) => row.link) ? (row) => row.link && navigate(row.link) : undefined}
              minWidth={720}
              caption={label}
              empty={<EmptyState icon={BarChart3} text="No records match these filters. Widen the dates or clear a filter." />}
            />
          </div>
          {r?.note && <p className="border-t border-ims-divider px-5 py-3 text-t-small text-ims-muted">{r.note.replace(/\b\d{4}-\d{2}-\d{2}\b/g, (d) => fmtDate(d))}</p>}
        </Card>
      </div>
    </Page>
  );
}
